    pub hdr: u64,
    pub size: u64,
    pub body: u64,
    pub flag: u8,
}

fn oct_u64(buf: &[u8]) -> Result<u64, i32> {
    let field = buf.split(|b| *b == 0).next().unwrap_or(buf);
    let text = std::str::from_utf8(field).map_err(|_| 1)?.trim();
    if text.is_empty() { return Ok(0); }
    u64::from_str_radix(text, 8).map_err(|_| 1)
}

pub fn scan(path: &str) -> Result<Vec<Row>, i32> {
    let raw = std::fs::read(path).map_err(|_| 1)?;
    if raw.len() < 1024 || raw.len() % 512 != 0 { return Err(1); }
    let mut rows = Vec::new();
    let mut off = 0usize;
    let mut zeros = 0usize;
    while off + 512 <= raw.len() {
        let blk = &raw[off..off + 512];
        if blk.iter().all(|b| *b == 0) {
            zeros += 1;
            off += 512;
            if zeros == 2 { break; }
            continue;
        }
        if zeros != 0 || &blk[257..262] != b"ustar" { return Err(1); }
        let nlen = blk[..100].iter().position(|b| *b == 0).unwrap_or(100);
        if nlen == 0 { return Err(1); }
        let name = std::str::from_utf8(&blk[..nlen]).map_err(|_| 1)?.to_string();
        let size = oct_u64(&blk[124..136])?;
        let padded = size.checked_add(511).ok_or(1)? / 512 * 512;
        let end = (off as u64).checked_add(512).and_then(|x| x.checked_add(padded)).ok_or(1)?;
        if end > raw.len() as u64 { return Err(1); }
        rows.push(Row { name, hdr: off as u64, size, body: (off + 512) as u64, flag: blk[156] });
        off = end as usize;
    }
    if rows.is_empty() || zeros < 2 { return Err(1); }
    Ok(rows)
}
