pub fn rib_b(a: &str, b: &str) -> Result<Pack, i32> {
    let recs = read_idx(b)?;
    if recs.is_empty() { return Err(1); }
    let archive = std::fs::read(a).map_err(|_| 1)?;
    let mut confs: Vec<(String, u64, Vec<u8>)> = Vec::new();
    let mut logs = Vec::new();
    let mut names = Vec::new();
    for (i, r) in recs.iter().enumerate() {
        names.push(r.name.clone());
        let blob = load(&archive, r.body, r.size)?;
        if r.name.ends_with("sys.conf") { confs.push((r.name.clone(), i as u64, blob)); }
        else if r.name.ends_with("app.log") { logs.push(blob); }
    }
    let picked = first::keep_head(&confs).ok_or(1)?;
    let map = kv::pairs(picked);
    let t = map.get("timezone").cloned().ok_or(1)?;
    let c = map.get("cluster").cloned().ok_or(1)?;
    let mut e = Vec::new();
    for blob in logs {
        for line in String::from_utf8_lossy(&blob).lines() {
            let value = line.trim();
            if !value.is_empty() { e.push(value.to_string()); }
        }
    }
    e.sort(); e.dedup();
    let s = std::path::Path::new(a).file_name().and_then(|x| x.to_str()).ok_or(1)?.to_string();
    Ok(Pack { t, c, e, n: recs.len() as u32, s, w: digest(&names.join("\n"))? })
}
